/*
 * GETUP.C  CPU get-up, quick stand and pattern choice tables
 *
 * By character and CPU level: Get_Up_Action_Check_Data replaces a get-up action that does not suit the
 * screen area, and Get_Up_Action_Tech_Data gives four random pattern pairs for it;
 * Receive_Data is the chance, by opponent rank and level, of a quick stand. Read by COM_PL.C.
 * Active_A_Unit_Data .. Active_D_Unit_Data pick the active pattern by area, level and one of 32
 * random draws, SA_Active_A_Unit_Data .. SA_Active_D_Unit_Data the pattern while a super art
 * is ready, and Passive_A_Unit_Data_04 .. Passive_C_Unit_Data_04 the passive pattern for
 * screen areas A to C by character, the opponent technique seen, level and a random draw; read
 * by COM_SUB.C.
 */

